//! Comparisons with independent implementations: PROJ, GeodePy and DynAdjust.
//!
//! The reference values are in `tests/data`, generated by
//! `tests/oracle/generate.py` (versions in each file's first line), except
//! `natadjust_rvs_example.dat`, which is GeodePy's copy of DynAdjust output.
//! The data is compiled in, so these tests run natively and in the browser.

#![allow(clippy::unwrap_used)]

use gnss_datum::tm::{MgaZone, to_mga};
use gnss_datum::{CoordinateEpoch, Covariance, FrameId, GRS80, Geodetic, Position, transform};
use nalgebra::{Matrix3, Vector3};
#[cfg(target_arch = "wasm32")]
use wasm_bindgen_test::wasm_bindgen_test as test;

#[cfg(target_arch = "wasm32")]
wasm_bindgen_test::wasm_bindgen_test_configure!(run_in_browser);

/// Data rows of a generated CSV file, split into fields.
fn rows(text: &'static str) -> impl Iterator<Item = Vec<&'static str>> {
    text.lines()
        .filter(|l| !l.starts_with('#'))
        .skip(1)
        .map(|l| l.split(',').collect())
}

fn num(field: &str) -> f64 {
    field.parse().unwrap()
}

fn epoch(year: f64) -> CoordinateEpoch {
    CoordinateEpoch::from_decimal_year(year).unwrap()
}

/// Ground distance between two latitude/longitude pairs, in metres (small differences only).
fn ground_m(a: &Geodetic, lat_deg: f64, lon_deg: f64) -> f64 {
    let north = (a.latitude_deg() - lat_deg).to_radians() * 6_371_000.0;
    let east =
        (a.longitude_deg() - lon_deg).to_radians() * 6_371_000.0 * libm::cos(a.latitude_rad());
    libm::hypot(north, east)
}

#[test]
fn geodetic_and_ecef_match_proj() {
    let mut worst: f64 = 0.0;
    for r in rows(include_str!("data/geodetic_ecef.csv")) {
        let (lat, lon, h) = (num(r[0]), num(r[1]), num(r[2]));
        let proj = Vector3::new(num(r[3]), num(r[4]), num(r[5]));
        let ours = GRS80.geodetic_to_ecef(&Geodetic::from_degrees(lat, lon, h).unwrap());
        worst = worst.max((ours - proj).norm());
        let back = GRS80.ecef_to_geodetic(&proj).unwrap();
        worst = worst.max(ground_m(&back, lat, lon));
        worst = worst.max((back.ellipsoidal_height_m() - h).abs());
    }
    eprintln!("geodetic/ECEF vs PROJ: worst {worst:.1e} m");
    assert!(worst < 1e-8, "worst difference {worst} m");
}

#[test]
fn mga_matches_proj() {
    let (mut worst_m, mut worst_k, mut worst_gamma_deg): (f64, f64, f64) = (0.0, 0.0, 0.0);
    for r in rows(include_str!("data/mga_proj.csv")) {
        let (lat, lon) = (num(r[0]), num(r[1]));
        let tm = MgaZone::new(r[2].parse().unwrap()).unwrap().projection();
        let (e, n, k, gamma) = (num(r[3]), num(r[4]), num(r[5]), num(r[6]));
        let p = tm
            .forward(&Geodetic::from_degrees(lat, lon, 0.0).unwrap())
            .unwrap();
        worst_m = worst_m.max(libm::hypot(p.easting_m - e, p.northing_m - n));
        worst_k = worst_k.max((p.point_scale_factor - k).abs());
        worst_gamma_deg = worst_gamma_deg.max((p.grid_convergence_rad.to_degrees() - gamma).abs());
        let (g, _) = tm.inverse(e, n).unwrap();
        worst_m = worst_m.max(ground_m(&g, lat, lon));
    }
    eprintln!(
        "MGA vs PROJ: worst {worst_m:.1e} m, k {worst_k:.1e}, convergence {worst_gamma_deg:.1e}°"
    );
    assert!(worst_m < 1e-6, "coordinates differ by up to {worst_m} m");
    // PROJ computes factors by numerical differentiation, good to about 1e-9.
    assert!(worst_k < 1e-8, "point scale differs by up to {worst_k}");
    assert!(
        worst_gamma_deg < 1e-8,
        "convergence differs by up to {worst_gamma_deg}°"
    );
}

#[test]
fn mga_matches_geodepy() {
    let (mut worst_m, mut worst_k, mut worst_gamma_deg): (f64, f64, f64) = (0.0, 0.0, 0.0);
    for r in rows(include_str!("data/mga_geodepy.csv")) {
        let (lat, lon) = (num(r[0]), num(r[1]));
        let tm = MgaZone::new(r[2].parse().unwrap()).unwrap().projection();
        let p = tm
            .forward(&Geodetic::from_degrees(lat, lon, 0.0).unwrap())
            .unwrap();
        worst_m = worst_m.max(
            (p.easting_m - num(r[3]))
                .abs()
                .max((p.northing_m - num(r[4])).abs()),
        );
        worst_k = worst_k.max((p.point_scale_factor - num(r[5])).abs());
        worst_gamma_deg =
            worst_gamma_deg.max((p.grid_convergence_rad.to_degrees() - num(r[6])).abs());
    }
    eprintln!(
        "MGA vs GeodePy: worst {worst_m:.1e} m, k {worst_k:.1e}, convergence {worst_gamma_deg:.1e}°"
    );
    // GeodePy rounds coordinates to 0.1 mm and point scale to 8 decimals.
    assert!(
        worst_m <= 5e-5 + 1e-9,
        "coordinates differ by up to {worst_m} m"
    );
    assert!(
        worst_k <= 5e-9 + 1e-12,
        "point scale differs by up to {worst_k}"
    );
    assert!(
        worst_gamma_deg < 1e-9,
        "convergence differs by up to {worst_gamma_deg}°"
    );
}

/// The source frame, epoch and target of a named case in the generated Helmert files.
fn case(
    name: &str,
    t: f64,
) -> (
    FrameId,
    Option<CoordinateEpoch>,
    FrameId,
    Option<CoordinateEpoch>,
) {
    match name {
        "gda94_gda2020" => (FrameId::Gda94, None, FrameId::Gda2020, None),
        "itrf2014_gda2020" => (FrameId::Itrf2014, Some(epoch(t)), FrameId::Gda2020, None),
        "gda2020_itrf2014" => (FrameId::Gda2020, None, FrameId::Itrf2014, Some(epoch(t))),
        "gda2020_atrf2014" => (FrameId::Gda2020, None, FrameId::Atrf2014, Some(epoch(t))),
        "itrf2020_itrf2014" => (
            FrameId::Itrf2020,
            Some(epoch(t)),
            FrameId::Itrf2014,
            Some(epoch(t)),
        ),
        "itrf2008_itrf2014" => (
            FrameId::Itrf2008,
            Some(epoch(t)),
            FrameId::Itrf2014,
            Some(epoch(t)),
        ),
        "itrf2020_itrf2008" => (
            FrameId::Itrf2020,
            Some(epoch(t)),
            FrameId::Itrf2008,
            Some(epoch(t)),
        ),
        "itrf2005_itrf2008" => (
            FrameId::Itrf2005,
            Some(epoch(t)),
            FrameId::Itrf2008,
            Some(epoch(t)),
        ),
        other => panic!("unknown case {other}"),
    }
}

#[test]
fn helmert_transformations_match_proj() {
    let mut worst: f64 = 0.0;
    let mut count = 0;
    for r in rows(include_str!("data/helmert_proj.csv")) {
        let (from, from_epoch, to, to_epoch) = case(r[0], num(r[1]));
        let xyz = Vector3::new(num(r[2]), num(r[3]), num(r[4]));
        let expected = Vector3::new(num(r[5]), num(r[6]), num(r[7]));
        let p = Position::new(from, from_epoch, xyz, None).unwrap();
        let t = transform(&p, to, to_epoch).unwrap();
        worst = worst.max((t.position.xyz() - expected).norm());
        count += 1;
    }
    assert!(count > 500);
    eprintln!("Helmert vs PROJ ({count} cases): worst {worst:.1e} m");
    // Both evaluate the same linearised formula. For reverse transformations
    // PROJ undoes the translation and scale exactly where we negate the
    // parameters, which differs by a few picometres: below a double's
    // resolution at these distances.
    assert!(worst < 1e-8, "worst difference {worst} m");
}

#[test]
fn helmert_covariances_match_geodepy() {
    let (mut worst_m, mut worst_cov): (f64, f64) = (0.0, 0.0);
    for r in rows(include_str!("data/helmert_geodepy.csv")) {
        let (from, from_epoch, to, to_epoch) = case(r[0], num(r[1]));
        let sym = |o: usize| {
            let v: Vec<f64> = r[o..o + 6].iter().map(|f| num(f)).collect();
            Matrix3::new(v[0], v[1], v[2], v[1], v[3], v[4], v[2], v[4], v[5])
        };
        let xyz = Vector3::new(num(r[2]), num(r[3]), num(r[4]));
        let cov = Covariance::new(sym(5)).unwrap();
        let expected_xyz = Vector3::new(num(r[11]), num(r[12]), num(r[13]));
        let expected_cov = sym(14);

        let p = Position::new(from, from_epoch, xyz, Some(cov)).unwrap();
        let t = transform(&p, to, to_epoch).unwrap();
        worst_m = worst_m.max((t.position.xyz() - expected_xyz).norm());
        // GeodePy adds the transformation's uncertainty to the point's; we keep them apart.
        let ours = t.position.covariance().unwrap().matrix() + t.transformation_covariance;
        worst_cov = worst_cov.max((ours - expected_cov).abs().max() / expected_cov.abs().max());
    }
    eprintln!("Helmert vs GeodePy: worst {worst_m:.1e} m, covariance {worst_cov:.1e} relative");
    assert!(worst_m < 1e-6, "coordinates differ by up to {worst_m} m");
    assert!(
        worst_cov < 1e-9,
        "covariances differ by up to {worst_cov} (relative)"
    );
}

/// Hours-minutes-seconds notation, DDD.MMSSsss, to decimal degrees, exactly as written.
fn hp_to_degrees(field: &str) -> f64 {
    let negative = field.starts_with('-');
    let (whole, fraction) = field.trim_start_matches('-').split_once('.').unwrap();
    let minutes: f64 = fraction[..2].parse().unwrap();
    let seconds: f64 = format!("{}.{}", &fraction[2..4], &fraction[4..])
        .parse()
        .unwrap();
    let degrees = num(whole) + minutes / 60.0 + seconds / 3600.0;
    if negative { -degrees } else { degrees }
}

#[test]
fn rvs_stations_match_dynadjust() {
    // GDA2020 coordinates of the 109 Recognised Value Standard CORS, as
    // DynAdjust wrote them: E, N and zone; latitude and longitude in
    // DDD.MMSSsssss; AHD and ellipsoidal heights; X, Y, Z.
    let text = include_str!("data/natadjust_rvs_example.dat");
    let mut stations = 0;
    let (mut worst_xyz, mut worst_mga): (f64, f64) = (0.0, 0.0);
    for line in text.lines().filter(|l| !l.trim().is_empty()) {
        let f: Vec<&str> = line.split_whitespace().collect();
        let (e, n, zone) = (num(f[2]), num(f[3]), f[4].parse::<u8>().unwrap());
        let (lat, lon, h) = (hp_to_degrees(f[5]), hp_to_degrees(f[6]), num(f[8]));
        let xyz = Vector3::new(num(f[9]), num(f[10]), num(f[11]));

        let g = Geodetic::from_degrees(lat, lon, h).unwrap();
        let p = Position::from_geodetic(FrameId::Gda2020, None, &g, None).unwrap();
        worst_xyz = worst_xyz.max((p.xyz() - xyz).abs().max());
        let (mga, _) = to_mga(&p, Some(MgaZone::new(zone).unwrap())).unwrap();
        worst_mga = worst_mga.max((mga.easting_m - e).abs().max((mga.northing_m - n).abs()));
        stations += 1;
    }
    assert_eq!(stations, 109);
    eprintln!("RVS vs DynAdjust: worst XYZ {worst_xyz:.1e} m, MGA {worst_mga:.1e} m");
    // Latitude and longitude are written to 1e-5 arcseconds (0.3 mm), and the
    // rest to 0.1 mm.
    assert!(worst_xyz < 4e-4, "XYZ differs by up to {worst_xyz} m");
    assert!(worst_mga < 4e-4, "MGA differs by up to {worst_mga} m");
}
